INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 32, 'theory', 'Quiz: package managers and semver');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 32, 0, 'Which versions does the range ^1.2.3 allow?', '["Only 1.2.3", "Any ≥ 1.2.3 and < 2.0.0", "Any ≥ 1.2.3 and < 1.3.0", "Any 1.x.x version, including 1.0.0"]', 1, 'The caret allows updates that don''t change the leftmost non-zero part: ^1.2.3 = >=1.2.3 <2.0.0. ~1.2.3 = >=1.2.3 <1.3.0.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 32, 1, 'What is a lock file for?', '["To forbid publishing the package", "To pin the exact versions and hashes of every package in the tree — a reproducible install", "To speed up running scripts", "To store passwords"]', 1, 'Ranges in the manifest produce different versions at different times; the lock file records specific ones, and npm ci installs strictly from it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 32, 2, 'What is a “phantom dependency”?', '["A package that cannot be removed", "Code imports a package that is not in the manifest but happens to be nearby because of hoisting in node_modules", "A dependency without a version", "A dependency on a private registry"]', 1, 'Because of hoisting, other packages'' dependencies are visible to the project. This breaks on updates; pnpm makes such imports impossible.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 32, 3, 'What does 1.0.0-beta.2 mean compared with 1.0.0?', '["The version is newer", "The version is older: a prerelease ranks below the release", "The versions are not comparable", "They are the same"]', 1, 'According to semver, a prerelease version has lower precedence than the release with the same numbers.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 32, 4, 'What is the main difference in how pnpm stores packages?', '["It doesn''t use a registry", "Files are stored once in a shared store and connected with hard links; node_modules is strict", "It keeps packages in the cloud", "It doesn''t create a lock file"]', 1, 'A single content-addressable store saves space and time, and the node_modules layout exposes only declared dependencies.');
